Step.Calculation:
JSONSetElement ( "{}" ;
	[ "success" ; False ; JSONBoolean ] ;
	[ "error" ; "Companion server unreachable (error " & $httpError & ")" ; JSONString ]
)

Value.Calculation:
JSONSetElement ( $context ;
	[ "snapshot_path" ; "agent/context/snapshot.xml" ; JSONString ] ;
	[ "snapshot_timestamp" ; GetAsText ( Get ( CurrentTimestamp ) ) ; JSONString ]
)

Let (
	~date = GetAsDate ( $now ) ;
	Year ( ~date ) & "-" & Right ( "0" & Month ( ~date ) ; 2 ) & "-" & Right ( "0" & Day ( ~date ) ; 2 )
)

Let (
	~time = GetAsTime ( $now ) ;
	$today & "_" & Right ( "0" & Hour ( ~time ) ; 2 ) & Right ( "0" & Minute ( ~time ) ; 2 ) & Right ( "0" & Int ( Seconds ( ~time ) ) ; 2 )
)

Let (
	[
		~prefix = If ( Get ( SystemPlatform ) = -2 ; "filewin:" ; "filemac:" ) ;
		~root = Get ( TemporaryPath )
	] ;
	~prefix & ~root & If ( Right ( ~root ; 1 ) = "/" ; "" ; "/" ) & "SaXML_" & Get ( FileName ) & "_" & $stamp & "/"
)

Let ( [
		~windows = Get ( SystemPlatform ) = -2 ;
		~prefix = If ( Left ( $output ; 4 ) = "file" ; "" ; If ( ~windows ; "filewin:" ; "filemac:" ) )
	] ;
	ConvertFromFileMakerPath ( ~prefix & $output ; If ( ~windows ; 2 ; 1 ) )
)

Let ( [
			~fp = Get ( FilePath ) ;
			~windows = Get ( SystemPlatform ) = -2 ;
			~sep = If ( ~windows ; "\\" ; "/" ) ;
			~folder = Left ( ~fp ; Position ( ~fp ; "/" ; Length ( ~fp ) ; -1 ) ) ;
			~folderFM = If ( Left ( ~folder ; 5 ) = "file:" ; If ( ~windows ; "filewin:" ; "filemac:" ) & Middle ( ~folder ; 6 ; Length ( ~folder ) ) ; ~folder ) ;
			~native = ConvertFromFileMakerPath ( ~folderFM ; If ( ~windows ; 2 ; 1 ) )
		] ;
		If ( Left ( ~fp ; 6 ) = "fmnet:" ;
			Middle ( ~fp ; 8 ; Position ( ~fp ; "/" ; 8 ; 1 ) - 8 ) ;
			~native & If ( Right ( ~native ; 1 ) = ~sep ; "" ; ~sep )
		)
	)

JSONSetElement ( "{}" ;
	[ "solution_name" ; $solutionName ; JSONString ] ;
	[ "stage" ; "export" ; JSONString ] ;
	[ "event" ; "file_start" ; JSONString ] ;
	[ "file" ; $fileName & ".fmp12" ; JSONString ] ;
	[ "index" ; $i ; JSONNumber ] ;
	[ "total" ; $fileCount ; JSONNumber ]
)

Let (
	~error = Get ( LastError ) ;
	If ( ~error ≠ 0 ; "Save a Copy as XML failed (error " & ~error & ")" ; "" )
)

Let ( [
			~name = Substitute ( $fileName ; [ Char ( 38 ) ; Char ( 38 ) & "amp;" ] ; [ Char ( 60 ) ; Char ( 38 ) & "lt;" ] ; [ Char ( 62 ) ; Char ( 38 ) & "gt;" ] ; [ Char ( 34 ) ; Char ( 38 ) & "quot;" ] ) ;
			~filePath = Substitute ( $filePath ; [ Char ( 38 ) ; Char ( 38 ) & "amp;" ] ; [ Char ( 60 ) ; Char ( 38 ) & "lt;" ] ; [ Char ( 62 ) ; Char ( 38 ) & "gt;" ] ; [ Char ( 34 ) ; Char ( 38 ) & "quot;" ] ) ;
			~path = Substitute ( $outputNative ; [ Char ( 38 ) ; Char ( 38 ) & "amp;" ] ; [ Char ( 60 ) ; Char ( 38 ) & "lt;" ] ; [ Char ( 62 ) ; Char ( 38 ) & "gt;" ] ; [ Char ( 34 ) ; Char ( 38 ) & "quot;" ] )
		] ;
		List (
			$summaryFiles ;
			"	<File name=\"" & ~name & ".fmp12\" path=\"" & ~filePath & "\">" & ¶ &
			"		<XML path=\"" & ~path & "\"></XML>" & ¶ &
			"	</File>"
		)
	)

JSONSetElement ( "{}" ;
	[ "solution_name" ; $solutionName ; JSONString ] ;
	[ "stage" ; "export" ; JSONString ] ;
	[ "event" ; "done" ; JSONString ] ;
	[ "file" ; "" ; JSONString ] ;
	[ "index" ; $fileCount ; JSONNumber ] ;
	[ "total" ; $fileCount ; JSONNumber ]
)

Let ( [
		~windows = Get ( SystemPlatform ) = -2 ;
		~sep = If ( ~windows ; "\\" ; "/" ) ;
		~native = ConvertFromFileMakerPath ( $exportFolder ; If ( ~windows ; 2 ; 1 ) )
	] ;
	If ( $fileCount = 1 ;
		$outputNative ;
		If ( Right ( ~native ; 1 ) = ~sep ; Left ( ~native ; Length ( ~native ) - 1 ) ; ~native )
	)
)

If ( Length ( $jobId ) ≠ 12 ;
	"NOT converted: " & Let ( ~error = JSONGetElement ( $response ; "error" ) ; If ( ~error = "?" ; $response ; ~error ) ) ;
	""
)

Let ( [
	~raw = JSONGetElement ( $status ; "progress" ) ;
	~p = If ( Left ( ~raw ; 1 ) = "?" ; "{}" ; ~raw ) ;
	~stage = JSONGetElement ( ~p ; "stage" ) ;
	~index = JSONGetElement ( ~p ; "index" ) ;
	~total = JSONGetElement ( ~p ; "total" ) ;
	~file = JSONGetElement ( ~p ; "file" ) ;
	~label = Case (
		~stage = "read" ; "Reading" ;
		~stage = "scrub" ; "Scrubbing" ;
		~stage = "analyze" ; "Analyzing" ;
		~stage = "write_raw" ; "Writing raw XML" ;
		~stage = "write_pages" ; "Writing pages" ;
		""
	) ;
	~seconds = Round ( Get ( CurrentTimestamp ) - $pollStart ; 0 )
] ;
	"Converting " & $solutionName & " - " &
	Case (
		$state = "queued" ; "waiting for another conversion" ;
		not IsEmpty ( ~label ) and GetAsNumber ( ~total ) > 0 ;
			~label & " " & ~index & " of " & ~total & If ( IsEmpty ( ~file ) or Left ( ~file ; 1 ) = "?" ; "" ; " (" & ~file & ")" ) ;
		"working"
	) &
	" - " & ~seconds & "s"
)

Case (
	$httpError ≠ 0 ;
		"Lost contact with the companion server while converting (error " & $httpError & "). Job " & $jobId & " may still be running: open " & $companionUrl & "/convert/" & $jobId & " to check." ;
	$state = "succeeded" ;
		Let ( [
			~c = JSONGetElement ( $status ; "counts" ) ;
			~viewer = JSONGetElement ( $status ; "viewer_path" ) ;
			~warnings = JSONGetElement ( $status ; "warning_count" )
		] ;
			"Converted " & JSONGetElement ( ~c ; "files" ) & " file(s) as solution " & $solutionName & ": " &
			JSONGetElement ( ~c ; "tables" ) & " tables, " &
			JSONGetElement ( ~c ; "fields" ) & " fields, " &
			JSONGetElement ( ~c ; "table_occurrences" ) & " table occurrences, " &
			JSONGetElement ( ~c ; "relationships" ) & " relationships, " &
			JSONGetElement ( ~c ; "layouts" ) & " layouts, " &
			JSONGetElement ( ~c ; "scripts" ) & " scripts." & ¶ &
			"Docs: " & JSONGetElement ( $status ; "output_path" ) &
			If ( not IsEmpty ( ~viewer ) and ~viewer ≠ "?" ; ¶ & "HTML viewer: " & ~viewer ; "" ) & ¶ &
			"Warnings: " & ~warnings & If ( GetAsNumber ( ~warnings ) > 0 ; " (see Reports/warnings.md in the docs folder)" ; "" )
		) ;
	$state = "failed" ;
		Let ( [
			~log = JSONGetElement ( $status ; "log_tail" )
		] ;
			"Conversion FAILED: " & JSONGetElement ( $status ; "error" ) &
			If ( IsEmpty ( ~log ) or ~log = "?" ; "" ; ¶ & ¶ & "End of fm-saxml's output:" & ¶ & Right ( ~log ; 800 ) )
		) ;
	$state = "queued" or $state = "running" ;
		"Still converting after 30 minutes. Job " & $jobId & " keeps running in the companion: open " & $companionUrl & "/convert/" & $jobId & " to check." ;
	"Unexpected answer from the companion server: " & $status
)

Step.Calculation:
JSONSetElement ( "{}" ;
	[ "success" ; False ; JSONBoolean ] ;
	[ "error" ; "Missing required key: layout" ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "success" ; True ; JSONBoolean ] ;
	[ "layout" ; Get ( LayoutName ) ; JSONString ] ;
	[ "tableOccurrence" ; Get ( LayoutTableName ) ; JSONString ]
)

Value.Calculation:
JSONSetElement ( "{}" ;
	[ "script" ; "Push Context" ; JSONString ] ;
	[ "parameter" ; "build invoice scripts" ; JSONString ]
)

Step.Calculation:
JSONSetElement ( "{}" ;
	[ "success" ; False ; JSONBoolean ] ;
	[ "error" ; "Invalid parameter: expected JSON object" ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "success" ; False ; JSONBoolean ] ;
	[ "error" ; "Script not found: " & $script ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "success" ; False ; JSONBoolean ] ;
	[ "error" ; "Invalid parameter: expected JSON object" ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "success" ; False ; JSONBoolean ] ;
	[ "error" ; "Missing required key: expression" ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "success" ; False ; JSONBoolean ] ;
	[ "error_code" ; $gotoError ; JSONNumber ] ;
	[ "error" ; "Go to Layout failed — layout not found: " & $layout ; JSONString ] ;
	[ "expression" ; $expression ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "success" ; $errorCode = 0 ; JSONBoolean ] ;
	[ "error_code" ; $errorCode ; JSONNumber ] ;
	[ "result" ; $result ; JSONString ] ;
	[ "expression" ; $expression ; JSONString ] ;
	[ "layout" ; Get ( LayoutName ) ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "success" ; False ; JSONBoolean ] ;
	[ "error" ; "No pending job — companion /pending returned empty" ; JSONString ]
)

Value.Calculation:
JSONSetElement ( "{}" ;
	[ "lastError" ; Get ( LastError ) ; JSONNumber ] ;
	[ "lastErrorLocation" ; Get ( LastErrorLocation ) ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "label" ; JSONGetElement ( $param ; "label" ) ; JSONString ] ;
	[ "vars" ; JSONGetElement ( $param ; "vars" ) ; JSONRaw ] ;
	[ "timestamp" ; Get ( CurrentTimestamp ) ; JSONString ] ;
	[ "lastError" ; JSONGetElement ( $errorContext ; "lastError" ) ; JSONNumber ] ;
	[ "lastErrorLocation" ; JSONGetElement ( $errorContext ; "lastErrorLocation" ) ; JSONString ]
)

Step.Calculation:
JSONSetElement ( "{}" ;
	[ "label" ; "after Insert from URL" ; JSONString ] ;
	[ "vars"  ; JSONSetElement ( "{}" ;
		[ "exitCode"  ; $exitCode  ; JSONString ] ;
		[ "httpError" ; $httpError ; JSONString ] ;
		[ "response"  ; $response  ; JSONString ]
	) ; JSONRaw ]
)
